<?php require_once '../../includes/auth.php';require_once '../../config/conexion.php';exigir_roles(['Administrador del sistema','Visualización y actualización']);csrf_validar();$id=(int)($_POST['id_neonato']??0);try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id_espacio FROM espacios_neonatales WHERE id_neonato=? AND estado_espacio=\'Ocupada\' FOR UPDATE');$q->execute([$id]);$s=$q->fetch();if(!$s)throw new RuntimeException('El ingreso ya no está activo.');$q=$pdo->prepare("INSERT INTO estado_neonato(id_neonato,id_espacio,estado_clinico,situacion_hospitalaria,peso_actual_gramos,actualizado_por) SELECT ?,?,estado_clinico,'Alta/Egreso',peso_actual_gramos,? FROM estado_neonato WHERE id_neonato=? ORDER BY id_estado DESC LIMIT 1");$q->execute([$id,$s['id_espacio'],$_SESSION['id_usuario'],$id]);$pdo->prepare("UPDATE espacios_neonatales SET estado_espacio='Disponible',id_neonato=NULL,id_medico=NULL,fecha_ingreso_ucin=NULL WHERE id_espacio=?")->execute([$s['id_espacio']]);$pdo->prepare("INSERT INTO historial_asignaciones(id_neonato,id_espacio_anterior,evento,id_usuario) VALUES(?,?,'Alta/Egreso',?)")->execute([$id,$s['id_espacio'],$_SESSION['id_usuario']]);registrar_bitacora($pdo,'espacios_neonatales',(string)$s['id_espacio'],'ALTA',null,['id_neonato'=>$id]);$pdo->commit();flash('ok','Egreso registrado y espacio liberado.');redirigir('index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[SCUCIN egreso] '.$e->getMessage());flash('error',$e->getMessage());redirigir('index.php');}
